const ENC_BLOB = {
  salt: "u3lqYhunr64Q4XVEwCtQFg==",
  iv: "cINwBsgx1zourk/4",
  iterations: 600000,
  data: ""
};

function b64ToBytes(b64) {
  const bin = atob(b64);
  const arr = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
  return arr;
}

async function dechiffrer(motDePasse) {
  const enc = new TextEncoder();
  const keyMaterial = await crypto.subtle.importKey(
    "raw", enc.encode(motDePasse), "PBKDF2", false, ["deriveKey"]
  );
  const key = await crypto.subtle.deriveKey(
    { name: "PBKDF2", salt: b64ToBytes(ENC_BLOB.salt), iterations: ENC_BLOB.iterations, hash: "SHA-256" },
    keyMaterial,
    { name: "AES-GCM", length: 256 },
    false,
    ["decrypt"]
  );
  const plainBuf = await crypto.subtle.decrypt(
    { name: "AES-GCM", iv: b64ToBytes(ENC_BLOB.iv) },
    key,
    b64ToBytes(ENC_BLOB.data)
  );
  return JSON.parse(new TextDecoder().decode(plainBuf));
}

(function(){
  var gate = document.getElementById('passGate');
  var input = document.getElementById('passInput');
  var btn = document.getElementById('passBtn');
  var err = document.getElementById('passErr');

  function demarrerAvecDonnees(d){
    gate.style.display = 'none';
    if (d && d.PROFIL && d.PROFIL !== 'direction') [300, 1000, 2000, 4000].forEach(function(t){ setTimeout(function(){ try { if (window.__ckShow) window.__ckShow(true); } catch(e) {} }, t); });
    window.demarrerApp(d);
  }

  // Cache local : si les donnees dechiffrees correspondent au fichier actuel
  // (meme cle de chiffrement) ET que le cache n'est pas trop vieux, pas besoin
  // de retaper le mot de passe. Au-dela de la duree de validite, le mot de
  // passe est redemande meme si les donnees n'ont pas change.
  // On attend que la page soit entierement chargee (window.demarrerApp doit
  // deja exister) avant de tenter le demarrage automatique depuis le cache.
  var DUREE_CACHE_MS = 10 * 60 * 1000; // 10 minutes
  try { ['tractCacheKey','tractCacheJSON','tractCacheDate'].forEach(function(k){ localStorage.removeItem(k); }); } catch(e) {}

  function essayerCache(){
    try {
      if (sessionStorage.getItem('tractCacheKey') === ENC_BLOB.data) {
        var horodatage = parseInt(sessionStorage.getItem('tractCacheDate') || '0', 10);
        if (!horodatage || (Date.now() - horodatage) > DUREE_CACHE_MS) {
          sessionStorage.removeItem('tractCacheKey');
          sessionStorage.removeItem('tractCacheJSON');
          sessionStorage.removeItem('tractCacheDate');
          return false;
        }
        var cache = sessionStorage.getItem('tractCacheJSON');
        if (cache) {
          demarrerAvecDonnees(JSON.parse(cache));
          return true;
        }
      }
    } catch(e) {}
    return false;
  }

  function initGate(){
    if (!essayerCache()) {
      input.focus();
    }
  }

  if (document.readyState === 'complete') {
    setTimeout(initGate, 50);
  } else {
    window.addEventListener('load', function(){ setTimeout(initGate, 50); });
  }

  /*PROFILS*/ window.__PROFILS = [{"id":"chef","salt":"13qsXZJkwHwllhZJW9kjsw==","iv":"qIABudgXYWcq/aqQ","data":"EpcnsOErBnyfdEQT4vQk6E7H5ttNVFGyZ7gVT+0D"},{"id":"achats","salt":"nmwYmz8MJikmCCBSh457mQ==","iv":"JDQK8J9E0FY3EKL3","data":"HxUgmm8tyYheYuZr7vnUIsz96K71KM/tVeKymVsg"}]; /*FINPROFILS*/
  // Profils : chaque mot de passe de profil ouvre une petite enveloppe qui contient le mot de passe general.
  function enveloppe(p, pw){
    var enc = new TextEncoder();
    return crypto.subtle.importKey('raw', enc.encode(pw), 'PBKDF2', false, ['deriveKey']).then(function(km){
      return crypto.subtle.deriveKey({ name: 'PBKDF2', salt: b64ToBytes(p.salt), iterations: 600000, hash: 'SHA-256' }, km, { name: 'AES-GCM', length: 256 }, false, ['decrypt']);
    }).then(function(k){ return crypto.subtle.decrypt({ name: 'AES-GCM', iv: b64ToBytes(p.iv) }, k, b64ToBytes(p.data)); })
      .then(function(b){ return new TextDecoder().decode(b); });
  }
  function viaProfil(pw){
    var chain = Promise.reject(new Error('aucun profil'));
    (window.__PROFILS || []).forEach(function(p){
      chain = chain.catch(function(){ return enveloppe(p, pw).then(function(gp){ return dechiffrer(gp).then(function(d){ d.PROFIL = p.id; d.__gp = gp; return d; }); }); });
    });
    return chain;
  }
  function tenter(){
    btn.disabled = true;
    err.textContent = '';
    dechiffrer(input.value).then(function(d){ d.PROFIL = d.PROFIL || 'direction'; return d; }).catch(function(){ return viaProfil(input.value); }).then(function(d){
      if(!d.AUTO||!d.AUTO.S){ var gp0=d.__gp||input.value; delete d.__gp; d.AUTO={G:gp0,S:{Hesingue:gp0,Sierentz:gp0,Waldighoffen:gp0,Mulhouse:gp0,Creation:gp0}}; }
      try {
        sessionStorage.setItem('tractCacheKey', ENC_BLOB.data);
        sessionStorage.setItem('tractCacheJSON', JSON.stringify(d));
        sessionStorage.setItem('tractCacheDate', String(Date.now()));
      } catch(e) {}
      delete d.__gp; demarrerAvecDonnees(d);
    }).catch(function(){
      err.textContent = 'Mot de passe incorrect';
      input.value = '';
      input.focus();
      btn.disabled = false;
    });
  }
  btn.addEventListener('click', tenter);
  input.addEventListener('keydown', function(e){ if (e.key === 'Enter') tenter(); });
})();
